(ns diplomat.document
  "GENERATED by jolt-diplomat-backend from the real Diplomat HIR.
  Do not hand-edit — see backend/src/main.rs for the generator, README.md for how this fits together."
  (:require [jolt.ffi :as ffi]
            [diplomat.runtime :as dr]
  ))

(dr/defopaque Document "Document_destroy")

(ffi/defcfn ^:private c-parse "jolt_Document_parse" [:string :size_t :bool :bool :bool :bool] :pointer)
(defn parse [text opts]
  (->Document (c-parse text (alength (.getBytes text)) (:tables opts) (:strikethrough opts) (:footnotes opts) (:tasklists opts)) (atom false))
)

(ffi/defcfn ^:private c-to-html "jolt_Document_to_html" [:pointer :pointer] :void)
(defn to-html [self]
  (dr/writeable-capture (fn [w__] (c-to-html (dr/ptr! self) w__)))
)

(ffi/defcfn ^:private c-heading-count "Document_heading_count" [:pointer] :uint)
(defn heading-count [self] (c-heading-count (dr/ptr! self)))

(ffi/defcfn ^:private c-source-len "Document_source_len" [:pointer] :uint)
(defn source-len [self] (c-source-len (dr/ptr! self)))

